#!/usr/bin/env python3
"""Shape-aware batching scheduler.

Groups requests by their 64-aligned prompt length (the ``seq_align`` shape
dimension) and then by a logarithmic bin of the generation length.  The
logarithmic bins keep decode padding small for short generations while still
coalescing the rare, latency-dominant long generations into shared batches.

A single global set of at most eight shape representatives is used for both
buckets so the combined shape count satisfies MAX_SHAPES=8.
"""

import json
import math
import os
import pathlib
from collections import defaultdict

from cost_model import HEADS, HIDDEN, align

GRAN = 64
MAX_SHAPES = 8

# Global representative seq_align values (all multiples of 64).  Shape choice
# does not change the analytical cost model's per-request prefill/decode work;
# it only controls the per-shape compile cost and must be >= the aligned prompt.
SHAPES = [64, 128, 320, 576, 1088, 1408, 1728, 2048]

# Logarithmic gen-length bin resolves: finer for short generations (where most
# requests live and pad ratio is sensitive), coarser for long ones.
GEN_BIN_RATIO = {
    "requests_bucket_1.jsonl": 0.08,
    "requests_bucket_2.jsonl": 0.15,
}


def load_requests(path):
    with open(path, "r") as f:
        return [json.loads(line) for line in f]


def shape_for(seq_align):
    for s in SHAPES:
        if s >= seq_align:
            return s
    return SHAPES[-1]


def _gen_bin(gen_len, ratio):
    return int(math.log(gen_len) / math.log(1.0 + ratio))


def build_plan(reqs, ratio, prefix):
    groups = defaultdict(list)
    for r in reqs:
        seq = align(r["prompt_len"], GRAN)
        key = (seq, _gen_bin(r["gen_len"], ratio))
        groups[key].append(r)

    records = []
    ordered = sorted(groups.items(), key=lambda kv: (kv[0][0], kv[0][1]))
    for i, ((seq, _), members) in enumerate(ordered):
        batch_id = f"{prefix}-{i:05d}"
        shape = {
            "seq_align": shape_for(max(align(r["prompt_len"], GRAN) for r in members)),
            "heads_align": HEADS,
            "hidden_align": HIDDEN,
        }
        for r in members:
            records.append({
                "request_id": r["request_id"],
                "batch_id": batch_id,
                "shape": dict(shape),
            })
    return records


def write_plan(path, records):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w") as f:
        for rec in records:
            f.write(json.dumps(rec) + "\n")


def main():
    root = pathlib.Path(__file__).resolve().parents[1]
    for bucket, prefix in (("1", "b1"), ("2", "b2")):
        name = f"requests_bucket_{bucket}.jsonl"
        reqs = load_requests(str(root / "input_data" / name))
        recs = build_plan(reqs, GEN_BIN_RATIO[name], prefix)
        write_plan(str(root / "output_data" / f"plan_{prefix}.jsonl"), recs)


if __name__ == "__main__":
    main()
